 35	static unsigned long long robot_motion_tool_now_ms(void)
 36	{
 37	  struct timespec ts;
 38	
 39	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
 40	    {
 41	      return 0;
 42	    }
 43	
 44	  return (unsigned long long)ts.tv_sec * 1000ULL +
 45	         (unsigned long long)ts.tv_nsec / 1000000ULL;
 46	}
