103	static int robot_motion_tool_number(cJSON *item, unsigned int minimum,
104	                                    unsigned int maximum,
105	                                    unsigned int *value)
106	{
107	  double number;
108	
109	  if (item == NULL || !cJSON_IsNumber(item) || value == NULL)
110	    {
111	      return -EINVAL;
112	    }
113	
114	  number = item->valuedouble;
115	  if (!(number >= minimum && number <= maximum) ||
116	      number != (double)(unsigned int)number)
117	    {
118	      return -EINVAL;
119	    }
120	
121	  *value = (unsigned int)number;
122	  return 0;
123	}
