125	static int robot_motion_tool_execute_move(const char *name,
126	                                          const char *input_json,
127	                                          char *output, size_t output_size)
128	{
129	  cJSON *root;
130	  cJSON *direction_item;
131	  cJSON *steps_item;
132	  cJSON *period_item;
133	  const char *direction_name;
134	  enum robot_motion_direction_e direction;
135	  unsigned int steps = ROBOT_MOTION_DEFAULT_STEPS;
136	  unsigned int period_ms;
137	  int ret;
138	
139	  if (name == NULL || input_json == NULL || output == NULL ||
140	      output_size == 0 || strcmp(name, ROBOT_MOTION_TOOL_NAME) != 0)
141	    {
142	      return ERROR;
143	    }
144	
145	  printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_ENTER\n",
146	         robot_motion_tool_now_ms());
147	  printf("[ROBOT-MOTION-TOOL] execute input=%s\n", input_json);
148	  root = cJSON_Parse(input_json);
149	  if (root == NULL)
150	    {
151	      snprintf(output, output_size,
152	               "{\"ok\":false,\"error\":\"invalid json\"}");
153	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
154	             robot_motion_tool_now_ms(), -EINVAL);
155	      return ERROR;
156	    }
157	
158	  direction_item = cJSON_GetObjectItem(root, "direction");
159	  direction_name = cJSON_GetStringValue(direction_item);
160	  ret = robot_motion_direction_from_name(direction_name, &direction);
161	  if (ret < 0)
162	    {
163	      cJSON_Delete(root);
164	      snprintf(output, output_size,
165	               "{\"ok\":false,\"error\":\"invalid direction\"}");
166	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
167	             robot_motion_tool_now_ms(), -EINVAL);
168	      return ERROR;
169	    }
170	
171	  period_ms = robot_motion_default_period(direction);
172	  steps_item = cJSON_GetObjectItem(root, "steps");
173	  if (steps_item != NULL &&
174	      robot_motion_tool_number(steps_item, ROBOT_MOTION_MIN_STEPS, 1,
175	                               &steps) < 0)
176	    {
177	      cJSON_Delete(root);
178	      snprintf(output, output_size,
179	               "{\"ok\":false,\"error\":\"steps must be 1\"}");
180	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
181	             robot_motion_tool_now_ms(), -EINVAL);
182	      return ERROR;
183	    }
184	
185	  period_item = cJSON_GetObjectItem(root, "period_ms");
186	  if (period_item != NULL &&
187	      robot_motion_tool_number(period_item, ROBOT_MOTION_MIN_PERIOD,
188	                               ROBOT_MOTION_MAX_PERIOD, &period_ms) < 0)
189	    {
190	      cJSON_Delete(root);
191	      snprintf(output, output_size,
192	               "{\"ok\":false,\"error\":\"period_ms must be 800..3000\"}");
193	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
194	             robot_motion_tool_now_ms(), -EINVAL);
195	      return ERROR;
196	    }
197	
198	  printf("[ROBOT-MOTION-TOOL] power-safe synchronous execution\n");
199	  printf("[ROBOT-MOTION-TOOL] direction=%s steps=%u period_ms=%u\n",
200	         direction_name, steps, period_ms);
201	  direction_name = robot_motion_direction_name(direction);
202	  cJSON_Delete(root);
203	  robot_action_guard_begin(ROBOT_ACTION_MOTION, ROBOT_MOTION_TOOL_NAME);
204	  ret = robot_motion_submit_and_wait(
205	    ROBOT_MOTION_SOURCE_AGENT, direction, steps, period_ms,
206	    robot_motion_default_timeout(steps, period_ms), NULL);
207	  robot_action_guard_end(ROBOT_ACTION_MOTION, ROBOT_MOTION_TOOL_NAME,
208	                         ret);
209	
210	  if (ret < 0)
211	    {
212	      if (ret == -EBUSY)
213	        {
214	          snprintf(output, output_size,
215	                   "{\"ok\":false,\"error\":\"motion_busy\"}");
216	        }
217	      else
218	        {
219	          snprintf(output, output_size,
220	                   "{\"ok\":false,\"error\":\"motion unavailable\","
221	                   "\"rc\":%d}", ret);
222	        }
223	      printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
224	             robot_motion_tool_now_ms(), ret);
225	      return ERROR;
226	    }
227	
228	  printf("[POWER-SAFE] mono_ms=%llu MOVE_TOOL_RETURN rc=%d\n",
229	         robot_motion_tool_now_ms(), ret);
230	  printf("[ROBOT-MOTION-TOOL] completed rc=%d\n", ret);
231	  snprintf(output, output_size,
232	           "{\"ok\":true,\"completed\":true,\"direction\":\"%s\","
233	           "\"steps\":%u,\"period_ms\":%u}", direction_name, steps,
234	           period_ms);
235	  return OK;
236	}
