312	  if (robot_music_media_is_active && robot_music_media_is_active()) companion = true;
313	
314	  cJSON_Delete(root);
315	  printf("[ROBOT-MOTION-TOOL] tail wag cycles=%u amplitude_deg=%u "
316	         "period_ms=%u\n", cycles, amplitude_deg, period_ms);
317	  robot_action_guard_begin(ROBOT_ACTION_MOTION, ROBOT_TAIL_WAG_TOOL_NAME);
318	  ret = companion ? robot_motion_music_tail_wag_sync(session_id, event_id,
319	                                                     period_ms, amplitude_deg) :
320	                    robot_motion_tail_wag_sync(ROBOT_MOTION_SOURCE_AGENT, cycles,
321	                                               period_ms, amplitude_deg);
322	  robot_action_guard_end(ROBOT_ACTION_MOTION, ROBOT_TAIL_WAG_TOOL_NAME, ret);
323	
324	  printf("[POWER-SAFE] mono_ms=%llu TAIL_WAG_TOOL_RETURN rc=%d\n",
325	         robot_motion_tool_now_ms(), ret);
326	  if (companion && (ret == -EAGAIN || ret == -EBUSY || ret == -ESTALE ||
327	                    ret == -EALREADY || ret == -EPERM || ret == -ECANCELED))
328	    {
329	      printf("[ROBOT-MUSIC] tail skipped session=%u rc=%d\n", session_id, ret);
330	      snprintf(output, output_size,
331	               "{\"ok\":true,\"skipped\":true,\"rc\":%d,\"retry\":false}", ret);
332	      return OK;
333	    }
334	  if (ret < 0)
335	    {
336	      snprintf(output, output_size,
337	               "{\"ok\":false,\"error\":\"tail wag unavailable\","
338	               "\"rc\":%d}", ret);
339	      return ERROR;
340	    }
341	
342	  snprintf(output, output_size,
343	           "{\"ok\":true,\"completed\":true,\"cycles\":%u,"
344	           "\"amplitude_deg\":%u,\"period_ms\":%u}", cycles, amplitude_deg,
345	           period_ms);
