365	      robot_motion_tool_number(cJSON_GetObjectItem(root, "music_session_id"), 1, UINT32_MAX, &session) < 0 ||
366	      robot_motion_tool_number(cJSON_GetObjectItem(root, "event_id"), 1, UINT32_MAX, &event) < 0)
367	    { cJSON_Delete(root); snprintf(output, output_size, "{\"ok\":false,\"error\":\"invalid music reaction token\"}"); return ERROR; }
368	  calm = reaction != NULL && strcmp(reaction, "listening") == 0;
369	  cJSON_Delete(root);
370	  robot_action_guard_begin(ROBOT_ACTION_EXPRESSION, ROBOT_MUSIC_REACT_TOOL_NAME);
371	  ret = robot_music_media_react(session, event, calm);
