373	  printf("[ROBOT-MUSIC] reaction session=%u event=%u rc=%d\n", session, event, ret);
374	  snprintf(output, output_size, "{\"ok\":%s,\"skipped\":%s,\"rc\":%d,\"retry\":false}",
375	    (ret == 0 || ret == -ESTALE || ret == -EALREADY) ? "true" : "false",
376	    ret == 0 ? "false" : "true", ret);
