 48	static uint64_t robot_proactive_monotonic_ms(void)
 49	{
 50	  struct timespec ts;
 51	
 52	  clock_gettime(CLOCK_MONOTONIC, &ts);
 53	  return (uint64_t)ts.tv_sec * 1000ULL +
 54	         (uint64_t)ts.tv_nsec / 1000000ULL;
 55	}
 56	
 57	static void robot_proactive_realtime_after_ms(struct timespec *ts,
 58	                                              uint32_t timeout_ms)
 59	{
 60	  clock_gettime(CLOCK_REALTIME, ts);
 61	  ts->tv_sec += (time_t)(timeout_ms / 1000U);
 62	  ts->tv_nsec += (long)(timeout_ms % 1000U) * 1000000L;
 63	  if (ts->tv_nsec >= 1000000000L)
 64	    {
 65	      ts->tv_sec++;
 66	      ts->tv_nsec -= 1000000000L;
 67	    }
 68	}
