137	static enum robot_expression_e
138	robot_expression_recompute_locked(uint64_t now_ms, bool *changed)
139	{
140	  unsigned int best_priority = 0;
141	  enum robot_expression_e next = ROBOT_EXPRESSION_IDLE;
142	  unsigned int source;
143	
144	  for (source = 0; source < ROBOT_EXPRESSION_SOURCE_COUNT; source++)
145	    {
146	      struct robot_expression_slot_s *slot = &g_slots[source];
147	
148	      if (!slot->active)
149	        {
150	          continue;
151	        }
152	
153	      if (slot->expires_ms != 0 && slot->expires_ms <= now_ms)
154	        {
155	          printf("[RV-EXPR] expire source=%s expression=%s generation=%u\n",
156	                 robot_expression_source_name(source),
157	                 robot_expression_name(slot->expression),
158	                 slot->generation);
159	          slot->active = false;
160	          slot->generation++;
161	          continue;
162	        }
163	
164	      if (g_source_priority[source] >= best_priority)
165	        {
166	          best_priority = g_source_priority[source];
167	          next = slot->expression;
168	        }
169	    }
170	
171	  *changed = next != g_effective;
172	  if (*changed)
173	    {
174	      g_effective = next;
175	    }
176	
177	  return next;
178	}
