180	static void *robot_expression_worker(void *arg)
181	{
182	  (void)arg;
183	
184	  for (;;)
185	    {
186	      bool changed = false;
187	      bool display_valid;
188	      bool need_submit;
189	      enum robot_expression_e expression;
190	
191	      /*
192	       * Expression expiry does not need a 50 ms scheduler tick.  A slower
193	       * poll substantially reduces SMP scheduling churn while Wi-Fi/audio
194	       * services are active, while still keeping short expressions visually
195	       * responsive (worst-case expiry delay is about 200 ms).
196	       */
197	      usleep(ROBOT_EXPRESSION_POLL_US);
198	
199	      pthread_mutex_lock(&g_expression_lock);
200	      if (g_expression_stop)
201	        {
202	          pthread_mutex_unlock(&g_expression_lock);
203	          break;
204	        }
205	
206	      expression =
207	          robot_expression_recompute_locked(robot_expression_now_ms(),
208	                                            &changed);
209	      display_valid = g_display_valid;
210	      pthread_mutex_unlock(&g_expression_lock);
211	
212	      /*
213	       * If a previous submission failed, retry only after the OLED worker
214	       * reports itself available.  This avoids a 50 ms error-log loop when
215	       * the panel is genuinely unavailable.
216	       */
217	
218	      need_submit =
219	          changed || (!display_valid && robot_oled_is_available());
220	
221	      if (need_submit)
222	        {
223	          (void)robot_expression_submit_display(expression);
224	
225	          if (changed)
226	            {
227	              printf("[RV-EXPR] effective=%s\n",
228	                     robot_expression_name(expression));
229	            }
230	        }
330	  pthread_mutex_unlock(&g_expression_lock);
331	  return 0;
332	}
