334	/*
335	 * duration_ms semantics:
336	 *   0  -> persistent until this source is explicitly changed or cleared
337	 *   >0 -> temporary request that expires after duration_ms
338	 *
339	 * Agent Tool calls intentionally use 0 so the selected facial expression
340	 * remains visible until the next requested expression.
341	 */
342	int robot_expression_set(enum robot_expression_source_e source,
343	                         enum robot_expression_e expression,
344	                         unsigned int duration_ms)
345	{
346	  bool changed = false;
347	  bool need_submit;
348	  enum robot_expression_e requested = expression;
349	  uint64_t now_ms;
350	  int ret;
351	
352	  if (source < 0 || source >= ROBOT_EXPRESSION_SOURCE_COUNT ||
353	      expression < 0 || expression >= ROBOT_EXPRESSION_COUNT)
354	    {
355	      return -EINVAL;
356	    }
357	
358	  if (duration_ms > ROBOT_EXPRESSION_MAX_MS)
359	    {
360	      return -ERANGE;
361	    }
362	
363	  if (robot_expression_init() < 0)
364	    {
365	      return -EIO;
366	    }
367	
368	  now_ms = robot_expression_now_ms();
369	
370	  pthread_mutex_lock(&g_expression_lock);
371	  g_slots[source].active = true;
372	  g_slots[source].expression = requested;
373	  g_slots[source].generation++;
374	  g_slots[source].expires_ms =
375	      duration_ms == 0 ? 0 : now_ms + duration_ms;
376	
377	  (void)robot_expression_recompute_locked(now_ms, &changed);
378	  expression = g_effective;
379	  need_submit = changed || !g_display_valid;
380	  pthread_mutex_unlock(&g_expression_lock);
381	
382	  if (need_submit)
383	    {
384	      ret = robot_expression_submit_display(expression);
385	      if (ret < 0)
386	        {
387	          return ret;
388	        }
389	    }
390	
391	  printf("[RV-EXPR] set source=%s requested=%s effective=%s duration=%u\n",
392	         robot_expression_source_name(source),
393	         robot_expression_name(requested),
394	         robot_expression_name(expression),
395	         duration_ms);
396	
397	  return 0;
398	}
