292	unsigned int robot_oled_animation_frame(enum robot_expression_e expression,
293	                                        uint32_t tick)
294	{
295	  uint32_t phase;
296	
297	  switch (expression)
298	    {
299	      case ROBOT_EXPRESSION_IDLE:
300	        /* About an 18 s personality loop at the OLED worker's 200 ms tick.
301	         * Most ticks map to frame 0, so they do not refresh the panel. */
302	        phase = tick % 90u;
303	        if (phase == 12u || phase == 42u)
304	          {
305	            return 1; /* blink */
306	          }
307	        if (phase == 24u || phase == 25u)
308	          {
309	            return 2; /* glance left */
310	          }
311	        if (phase == 30u || phase == 31u)
312	          {
313	            return 3; /* glance right */
314	          }
315	        if (phase >= 65u && phase <= 67u)
316	          {
317	            return 4; /* getting sleepy */
318	          }
319	        if (phase == 68u || phase == 72u)
320	          {
321	            return 5; /* small yawn */
322	          }
323	        if (phase >= 69u && phase <= 71u)
324	          {
325	            return 6; /* big yawn */
326	          }
327	        if (phase == 73u)
328	          {
329	            return 1; /* eyes closed after yawn */
330	          }
331	        return 0;
332	
333	      case ROBOT_EXPRESSION_LISTENING:
334	        phase = tick % 8u;
335	        if (phase == 2u || phase == 3u)
336	          {
337	            return 1;
338	          }
339	        if (phase == 6u || phase == 7u)
340	          {
341	            return 2;
342	          }
343	        return 0;
344	
345	      case ROBOT_EXPRESSION_THINKING:
346	        return (unsigned int)((tick / 2u) % 3u);
347	
348	      case ROBOT_EXPRESSION_SPEAKING:
349	        if ((tick % 20u) == 19u)
350	          {
351	            return 4; /* occasional blink */
352	          }
353	        return (unsigned int)(tick % 4u);
354	
355	      case ROBOT_EXPRESSION_HAPPY:
356	        return (tick % 14u) == 10u ? 1u : 0u;
357	
358	      case ROBOT_EXPRESSION_EXCITED:
359	        return (unsigned int)(tick % 3u);
360	
361	      case ROBOT_EXPRESSION_WINK:
362	        return (tick % 8u) < 2u ? 1u : 0u;
363	
364	      case ROBOT_EXPRESSION_LOVE:
365	        return (unsigned int)((tick / 2u) % 2u);
366	
367	      case ROBOT_EXPRESSION_SURPRISED:
368	        return (unsigned int)((tick / 2u) % 2u);
369	
370	      case ROBOT_EXPRESSION_COOL:
371	        return (unsigned int)((tick / 3u) % 2u);
372	
373	      case ROBOT_EXPRESSION_PLAYFUL:
374	        return (unsigned int)(tick % 3u);
375	
376	      case ROBOT_EXPRESSION_SLEEPY:
377	        phase = tick % 16u;
378	        if (phase >= 9u && phase <= 12u)
379	          {
380	            return 2; /* yawn */
381	          }
382	        return phase >= 6u ? 1u : 0u;
383	
384	      case ROBOT_EXPRESSION_SINGING:
385	        return (unsigned int)(tick % 4u);
386	
387	      case ROBOT_EXPRESSION_CURIOUS:
388	        return (unsigned int)((tick / 2u) % 3u);
389	
390	      case ROBOT_EXPRESSION_PROUD:
391	        return (unsigned int)((tick / 3u) % 2u);
392	
393	      case ROBOT_EXPRESSION_ERROR:
394	      default:
395	        return 0;

120	      pthread_mutex_lock(&g_music_lock);
121	      handle->users--;
122	      pthread_cond_broadcast(&g_music_changed);
123	      pthread_mutex_unlock(&g_music_lock);
124	    }
125	}
