134	/* The existing session worker drives the local policy. No second player,
135	 * status observer, periodic Agent message or network request is created. */
136	static void robot_music_companion_tick(struct rv_music_handle *handle, uint32_t worker_session)
137	{
138	  struct robot_world_state_s state;
139	  uint64_t now = robot_music_now_ms();
140	  uint32_t session = 0;
141	  uint32_t event = 0;
142	  bool tail_due = false;
143	  bool audible = robot_audio_playback_music_audible();
144	  if (robot_world_state_snapshot(&state) < 0) return;
145	  pthread_mutex_lock(&g_music_lock);
146	  if (handle->session_id != worker_session ||
147	      handle->closing || handle->stopping || !handle->started ||
148	      g_active_music != handle || !handle->companion_enabled ||
149	      !state.proactive_enabled || state.music_session_id != handle->session_id ||
150	      state.music_event_id != handle->companion_event_id ||
151	      state.conversation_active || state.tts_active)
152	    { pthread_mutex_unlock(&g_music_lock); return; }
153	  if (now >= handle->next_face_ms)
154	    {
155	      /* Two existing animated face resources; no fabricated beat detection.
156	       * A buffering song stays in the quieter listening expression. */
157	      bool quiet = handle->companion_calm || !audible || state.power_risk;
158	      int expression = quiet || (handle->face_index++ % 2) ?
159	                        ROBOT_EXPRESSION_LISTENING : ROBOT_EXPRESSION_HAPPY;
160	      int ret = robot_expression_set(ROBOT_EXPRESSION_SOURCE_AGENT, expression, 8000);
161	      handle->next_face_ms = now + MUSIC_FACE_INTERVAL_MS;
162	      printf("[ROBOT-MUSIC] face session=%lu expression=%d buffering=%d rc=%d\n",
163	        (unsigned long)handle->session_id, expression, !audible, ret);
164	    }
165	  if (handle->companion_tail && !handle->companion_calm &&
166	      now >= handle->next_tail_ms)
167	    {
168	      session = handle->session_id;
169	      event = handle->companion_event_id;
170	      handle->next_tail_ms = now + MUSIC_TAIL_RETRY_MS;
171	      tail_due = true;
172	    }
173	  pthread_mutex_unlock(&g_music_lock);
174	  if (tail_due)
175	    {
176	      int ret = robot_motion_music_tail_repeat_async(session, event);
177	      if (ret <= 0)
178	        {
179	          pthread_mutex_lock(&g_music_lock);
180	          if (g_active_music == handle && now >= handle->next_tail_log_ms)
181	            {
182	              handle->next_tail_log_ms = now + 10000ULL;
183	              printf("[ROBOT-MUSIC] periodic-tail waiting session=%lu rc=%d (buffer/power/busy gate)\n",
184	                (unsigned long)session, ret);
185	            }
186	          pthread_mutex_unlock(&g_music_lock);
187	        }
188	      if (ret > 0)
189	        {
190	          pthread_mutex_lock(&g_music_lock);
191	          if (g_active_music == handle && handle->companion_enabled)
192	            handle->next_tail_ms = now + MUSIC_TAIL_INTERVAL_MS;
193	          pthread_mutex_unlock(&g_music_lock);
194	          printf("[ROBOT-MUSIC] periodic-tail session=%lu request=%d next_ms=%llu\n",
195	            (unsigned long)session, ret, MUSIC_TAIL_INTERVAL_MS);
196	        }
197	    }
198	}
