200	static void *robot_music_confirm_worker(void *arg)
201	{
202	  struct rv_music_worker_arg *worker = arg;
203	  struct rv_music_handle *handle = worker->handle;
204	  uint32_t session = worker->session_id;
205	  free(worker);
206	
207	  for (;;)
208	    {
209	      uint64_t completed = 0;
210	      uint64_t pending = 0;
211	      int ret;
212	      pthread_mutex_lock(&g_music_lock);
213	      bool current = handle->session_id == session && !handle->closing &&
214	                     !handle->stopping && handle->started && g_active_music == handle;
215	      pthread_mutex_unlock(&g_music_lock);
216	      if (!current) break;
217	      ret = robot_audio_playback_progress(&completed, &pending);
218	      if (ret == 0 && completed != 0)
219	        {
220	          pthread_mutex_lock(&g_music_lock);
221	          if (handle->session_id == session &&
222	              !handle->closing && !handle->stopping && handle->started &&
223	              g_active_music == handle && !handle->announced)
224	            {
225	              ret = robot_proactive_music_session_update(ROBOT_MUSIC_PLAYING,
226	                handle->session_id, handle->track, "", "", 0);
227	              if (ret == 0)
228	                {
229	                  handle->announced = true;
230	                  syslog(LOG_INFO, "[ROBOT-MUSIC] DMA confirmed session=%lu completed=%llu pending=%llu\n",
231	                    (unsigned long)handle->session_id,
232	                    (unsigned long long)completed, (unsigned long long)pending);
233	                }
234	            }
235	          pthread_mutex_unlock(&g_music_lock);
236	        }
237	      robot_music_companion_tick(handle, session);
238	      usleep(100 * 1000);
239	    }
240	  pthread_mutex_lock(&g_music_lock);
241	  handle->users--;
242	  pthread_cond_broadcast(&g_music_changed);
243	  pthread_mutex_unlock(&g_music_lock);
244	  return NULL;
245	}
