248	{
249	  struct rv_music_handle *handle = calloc(1, sizeof(*handle));
250	  int ret;
251	  if (handle == NULL) { errno = ENOMEM; return NULL; }
252	  handle->player = robot_legacy_media_open(stream);
253	  if (handle->player == NULL) { free(handle); return NULL; }
254	  pthread_mutex_lock(&g_music_lock);
255	  handle->cookie_id = ++g_next_cookie;
256	  if (handle->cookie_id == 0) handle->cookie_id = ++g_next_cookie;
257	  handle->next = g_music_handles;
258	  g_music_handles = handle;
259	  pthread_mutex_unlock(&g_music_lock);
260	  ret = robot_legacy_media_set_event_callback(handle->player,
261	    (void *)handle->cookie_id, robot_music_media_event_bridge);
262	  if (ret < 0)
263	    {
264	      (void)robot_music_media_close(handle, 0);
265	      errno = -ret;
266	      return NULL;
