272	int robot_music_media_close(void *opaque, int pending_stop)
273	{
274	  struct rv_music_handle *handle = opaque;
275	  struct rv_music_handle **cursor;
276	  int ret;
277	  if (handle == NULL) return -EINVAL;
278	  pthread_mutex_lock(&g_music_lock);
279	  handle->closing = true;
280	  robot_music_media_end_locked(handle);
281	  pthread_mutex_unlock(&g_music_lock);
282	  (void)robot_legacy_media_set_event_callback(handle->player, NULL, NULL);
283	  pthread_mutex_lock(&g_music_lock);
284	  while (handle->users != 0)
285	    pthread_cond_wait(&g_music_changed, &g_music_lock);
286	  pthread_mutex_unlock(&g_music_lock);
287	  ret = robot_legacy_media_close(handle->player, pending_stop);
288	  pthread_mutex_lock(&g_music_lock);
289	  for (cursor = &g_music_handles; *cursor != NULL; cursor = &(*cursor)->next)
290	    if (*cursor == handle) { *cursor = handle->next; break; }
291	  pthread_mutex_unlock(&g_music_lock);
292	  free(handle);
293	  return ret;
294	}
