326	int robot_music_media_start(void *opaque)
327	{
328	  struct rv_music_handle *handle = opaque;
329	  pthread_t thread;
330	  pthread_attr_t attr;
331	  int ret;
332	  int confirm_ret;
333	  unsigned long run;
334	  if (handle == NULL) return -EINVAL;
335	  (void)robot_proactive_start();
336	  /* The voice run getter takes g_monitor.lock. Voice callbacks may already
337	   * hold that lock when querying music, so never call it under g_music_lock. */
338	  run = robot_voice_music_run_id != NULL ? robot_voice_music_run_id() : 0;
339	  pthread_mutex_lock(&g_music_lock);
340	  if (handle->closing || handle->started || handle->starting)
341	    { pthread_mutex_unlock(&g_music_lock); return -EBUSY; }
342	  handle->starting = true;
343	  handle->terminal_seen = false;
344	  handle->stopping = false;
345	  handle->announced = false;
346	  handle->stop_announced = false;
347	  handle->companion_enabled = false;
348	  handle->session_id = ++g_next_session;
349	  if (handle->session_id == 0) handle->session_id = ++g_next_session;
350	  handle->run = run;
351	  handle->users++;
352	  pthread_mutex_unlock(&g_music_lock);
353	  ret = robot_legacy_media_start(handle->player);
354	  pthread_mutex_lock(&g_music_lock);
355	  handle->starting = false;
356	  if (ret == 0 && !handle->closing && !handle->terminal_seen)
357	    {
358	      handle->started = true;
359	      g_active_music = handle;
360	      struct rv_music_worker_arg *worker = malloc(sizeof(*worker));
361	      if (worker != NULL)
362	        { worker->handle = handle; worker->session_id = handle->session_id; }
363	      handle->users++; /* confirmation/policy worker reference */
364	      confirm_ret = worker != NULL ? pthread_attr_init(&attr) : ENOMEM;
365	      if (confirm_ret == 0)
366	        {
367	          confirm_ret = pthread_attr_setstacksize(&attr, MUSIC_CONFIRM_STACK);
368	          if (confirm_ret == 0)
369	            confirm_ret = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
370	          if (confirm_ret == 0)
371	            confirm_ret = pthread_create(&thread, &attr, robot_music_confirm_worker, worker);
372	          pthread_attr_destroy(&attr);
373	        }
374	      if (confirm_ret != 0)
375	        {
376	          free(worker);
377	          handle->users--;
378	          syslog(LOG_WARNING, "[ROBOT-MUSIC] confirm worker unavailable rc=%d; music continues\n", confirm_ret);
379	        }
380	    }
381	  handle->users--;
382	  pthread_cond_broadcast(&g_music_changed);
383	  pthread_mutex_unlock(&g_music_lock);
384	  return ret;
385	}
