 932	int robot_motion_wait_timeout(uint32_t request_id, uint32_t timeout_ms,
 933	                              int *result)
 934	{
 935	  struct timespec start;
 936	  struct timespec deadline;
 937	  uint32_t elapsed;
 938	  uint32_t remaining;
 939	  uint32_t wait_ms;
 940	  int wait_ret;
 941	
 942	  if (request_id == 0 || timeout_ms == 0)
 943	    {
 944	      return -EINVAL;
 945	    }
 946	
 947	  if (clock_gettime(CLOCK_MONOTONIC, &start) != 0)
 948	    {
 949	      return -EIO;
 950	    }
 951	
 952	  pthread_mutex_lock(&g_motion.lock);
 953	  while (g_motion.completed_request_id < request_id)
 954	    {
 955	      elapsed = robot_motion_elapsed_ms(&start);
 956	      if (elapsed >= timeout_ms)
 957	        {
 958	          pthread_mutex_unlock(&g_motion.lock);
 959	          printf("[ROBOT-MOTION] wait timeout id=%lu elapsed_ms=%lu\n",
 960	                 (unsigned long)request_id, (unsigned long)elapsed);
 961	          return -ETIMEDOUT;
 962	        }
 963	
 964	      remaining = timeout_ms - elapsed;
 965	      wait_ms = remaining > 250 ? 250 : remaining;
 966	      if (clock_gettime(CLOCK_REALTIME, &deadline) != 0)
 967	        {
 968	          pthread_mutex_unlock(&g_motion.lock);
 969	          return -EIO;
 970	        }
 971	
 972	      deadline.tv_sec += wait_ms / 1000;
 973	      deadline.tv_nsec += (long)(wait_ms % 1000) * 1000000L;
 974	      if (deadline.tv_nsec >= 1000000000L)
 975	        {
 976	          deadline.tv_sec++;
 977	          deadline.tv_nsec -= 1000000000L;
 978	        }
 979	
 980	      wait_ret = pthread_cond_timedwait(&g_motion.cond, &g_motion.lock,
 981	                                        &deadline);
 982	      if (wait_ret != 0 && wait_ret != ETIMEDOUT)
 983	        {
 984	          pthread_mutex_unlock(&g_motion.lock);
 985	          return -wait_ret;
 986	        }
 987	    }
 988	
 989	  if (result != NULL)
 990	    {
 991	      *result = g_motion.last_result;
 992	    }
 993	  pthread_mutex_unlock(&g_motion.lock);
 994	  printf("[ROBOT-MOTION] wait complete id=%lu rc=%d\n",
 995	         (unsigned long)request_id, result != NULL ? *result : 0);
 996	  return 0;
 997	}
