1022	int robot_motion_submit_and_wait(enum robot_motion_source_e source,
1023	                                 enum robot_motion_direction_e direction,
1024	                                 unsigned int steps, unsigned int period_ms,
1025	                                 uint32_t timeout_ms, int *result)
1026	{
1027	  int request_id;
1028	  int motion_result;
1029	  int wait_result;
1030	
1031	  request_id = robot_motion_submit(source, direction, steps, period_ms);
1032	  if (request_id < 0)
1033	    {
1034	      return request_id;
1035	    }
1036	
1037	  printf("[ROBOT-MOTION] waiting id=%d timeout_ms=%lu\n", request_id,
1038	         (unsigned long)timeout_ms);
1039	  wait_result = robot_motion_wait_timeout((uint32_t)request_id, timeout_ms,
1040	                                          &motion_result);
1041	  if (wait_result == -ETIMEDOUT)
1042	    {
1043	      bool still_running;
1044	
1045	      pthread_mutex_lock(&g_motion.lock);
1046	      still_running = g_motion.completed_request_id < (uint32_t)request_id;
1047	      if (still_running)
1048	        {
1049	          g_motion.cancel_requested = true;
1050	        }
1051	      else
1052	        {
1053	          motion_result = g_motion.last_result;
1054	        }
1055	      pthread_mutex_unlock(&g_motion.lock);
1056	
1057	      if (still_running)
1058	        {
1059	          printf("[ROBOT-MOTION] timeout stop requested id=%d\n", request_id);
1060	          wait_result = robot_motion_wait((uint32_t)request_id,
1061	                                          &motion_result);
1062	          if (wait_result < 0)
1063	            {
1064	              return wait_result;
1065	            }
1066	
1067	          printf("[ROBOT-MOTION] timeout stopped id=%d worker_rc=%d\n",
1068	                 request_id, motion_result);
1069	          return -ETIMEDOUT;
1070	        }
1071	    }
1072	
1073	  if (wait_result < 0)
1074	    {
1075	      return wait_result;
1076	    }
1077	
1078	  if (result != NULL)
1079	    {
1080	      *result = motion_result;
1081	    }
1082	
1083	  return motion_result;
1084	}
