 226	  g_world.last_proactive_ms = robot_world_monotonic_ms();
 227	  g_world.last_event_id = event_id;
 228	  if (type >= 0 && type < ROBOT_EVENT_TYPE_COUNT)
 229	    {
 230	      g_world.last_event_type_ms[type] = g_world.last_proactive_ms;
 231	    }
 232	  if (event_id > g_world.last_processed_event_id)
 233	    g_world.last_processed_event_id = event_id;
 234	  if (type >= ROBOT_EVENT_MUSIC_STARTED && type <= ROBOT_EVENT_MUSIC_STOPPED)
 235	    g_world.last_music_event_id = event_id;
 236	  if (type == ROBOT_EVENT_IDLE_LONG)
 237	    {
