 244	bool robot_world_state_try_queue_idle(uint64_t now_ms, uint64_t idle_ms,
 245	                                      uint64_t cooldown_ms)
 246	{
 247	  bool accept = false;
 248	
 249	  pthread_mutex_lock(&g_world_lock);
 250	  if (g_world.initialized && g_world.proactive_enabled &&
 251	      g_world.user_has_interacted && !g_world.idle_event_fired &&
 252	      !g_world.idle_event_pending &&
 253	      now_ms - g_world.last_user_activity_ms >= idle_ms &&
 254	      (g_world.last_proactive_ms == 0 ||
 255	       now_ms - g_world.last_proactive_ms >= cooldown_ms))
 256	    {
 257	      g_world.idle_event_pending = true;
 258	      accept = true;
 259	    }
 260	  pthread_mutex_unlock(&g_world_lock);
 261	  return accept;
 262	}
