 264	void robot_world_state_cancel_idle_queue(void)
 265	{
 266	  pthread_mutex_lock(&g_world_lock);
 267	  g_world.idle_event_pending = false;
 268	  pthread_mutex_unlock(&g_world_lock);
 269	}
