229	/* One-degree pulses separated by unloaded recovery gaps. The request's
230	 * amplitude is the actual endpoint offset; only the tail channel is touched. */
231	#define ROBOT_MOTION_TAIL_SEGMENT_DEG 1
232	#define ROBOT_MOTION_TAIL_OPEN_RECOVERY_MS 500
233	#define ROBOT_MOTION_TAIL_ENDPOINT_SETTLE_MS 20
234	
235	static int robot_motion_tail_interval(unsigned int period_ms)
236	{
237	  (void)period_ms;
238	  return 20;
239	}
240	
241	static int robot_motion_tail_cooldown_ms(unsigned int period_ms,
242	                                         unsigned int amplitude_deg)
243	{
244	  /* center -> +A -> -A -> center has 4*A one-degree movements. */
245	  return (int)(period_ms / (4U * amplitude_deg)) -
246	         20 - ROBOT_MOTION_TAIL_ENDPOINT_SETTLE_MS;
247	}
248	
249	static int robot_motion_tail_cooldown(int cooldown_ms)
250	{
251	  while (cooldown_ms > 0)
252	    {
253	      int slice_ms = cooldown_ms > 25 ? 25 : cooldown_ms;
254	
255	      if (robot_motion_cancel_check(NULL))
256	        {
257	          return -ECANCELED;
258	        }
259	
260	      usleep((useconds_t)slice_ms * 1000);
261	      cooldown_ms -= slice_ms;
262	    }
263	
264	  return 0;
265	}
266	
267	static int robot_motion_tail_micro_move(struct robotctl_servo_ctx_s *ctx,
268	                                        int target, int interval_ms,
269	                                        int cooldown_ms)
270	{
271	  int ret;
272	
273	  ret = robotctl_servo_move_one(ctx, ROBOTCTL_TAIL, target,
274	                                interval_ms,
275	                                ROBOT_MOTION_TAIL_ENDPOINT_SETTLE_MS);
276	  if (ret < 0)
277	    {
278	      return ret;
279	    }
280	
281	  /*
282	   * robotctl_servo_move_one() stops PWM when the micro-move completes.  Keep
283	   * the rail unloaded briefly before the next one-degree segment.
284	   */
285	  return robot_motion_tail_cooldown(cooldown_ms);
286	}
287	
288	static int robot_motion_tail_ramp_to(struct robotctl_servo_ctx_s *ctx,
289	                                     int target, int interval_ms,
290	                                     int cooldown_ms)
291	{
292	  int current;
293	  int next;
294	  int delta;
295	  int ret;
296	
297	  if (ctx == NULL)
298	    {
299	      return -EINVAL;
300	    }
301	
302	  current = ctx->angle[ROBOTCTL_TAIL];
303	  while (current != target)
304	    {
305	      if (robot_motion_cancel_check(NULL))
306	        {
307	          return -ECANCELED;
308	        }
309	
310	      delta = target - current;
311	      next = current + (delta > 0 ? ROBOT_MOTION_TAIL_SEGMENT_DEG :
312	                                     -ROBOT_MOTION_TAIL_SEGMENT_DEG);
313	
314	      printf("[ROBOT-MOTION] tail soft-step %d -> %d target=%d\n",
315	             current, next, target);
316	      ret = robot_motion_tail_micro_move(ctx, next, interval_ms, cooldown_ms);
317	      if (ret < 0)
318	        {
319	          return ret;
320	        }
321	
322	      current = ctx->angle[ROBOTCTL_TAIL];
323	    }
324	
325	  return 0;
326	}
