328	static int robot_motion_home_power_safe(struct robotctl_servo_ctx_s *ctx,
329	                                        bool include_tail)
330	{
331	  int count = include_tail ? ROBOTCTL_SERVO_COUNT : ROBOTCTL_SERVO_COUNT - 1;
332	  int i;
333	
334	  for (i = 0; i < count; i++)
335	    {
336	      enum robotctl_servo_e servo = g_home_order[i];
337	      int ret;
338	
339	      if (robot_motion_music_active()) return -ECANCELED;
340	      printf("[ROBOT-MOTION] home move %s %d -> %d update=%s\n",
341	             robotctl_servo_name(servo), ctx->angle[servo],
342	             g_robotctl_home[servo],
343	             ctx->angle_known[servo] &&
344	             ctx->angle[servo] == g_robotctl_home[servo] ? "no" : "yes");
345	      ret = robotctl_servo_move_one(ctx, servo, g_robotctl_home[servo],
346	                                    ROBOT_MOTION_HOME_INTERVAL_MS,
347	                                    ROBOT_MOTION_HOME_SETTLE_MS);
348	      if (ret < 0)
349	        {
350	          return ret;
351	        }
352	    }
353	
354	  return 0;
355	}
