357	static enum robot_motion_phase_power_e robot_motion_phase_power(
358	    const struct robotctl_servo_ctx_s *ctx,
359	    const struct robot_motion_phase_s *phase, unsigned int *active)
360	{
361	  unsigned int count = 0;
362	  unsigned int delta = 0;
363	  unsigned int order;
364	
365	  for (order = 0; order < 2; order++)
366	    {
367	      enum robotctl_servo_e servo = phase->order[order];
368	      int difference = phase->target[servo] - ctx->angle[servo];
369	
370	      if (difference != 0)
371	        {
372	          count++;
373	          delta += (unsigned int)abs(difference);
374	        }
375	    }
376	
377	  if (active != NULL)
378	    {
379	      *active = count;
380	    }
381	
382	  if (count >= 2 && delta >= 45)
383	    {
384	      return ROBOT_MOTION_PHASE_HEAVY;
385	    }
386	
387	  return count == 0 ? ROBOT_MOTION_PHASE_LIGHT :
388	                      ROBOT_MOTION_PHASE_MEDIUM;
389	}
390	
391	static const char *robot_motion_phase_power_name(
392	    enum robot_motion_phase_power_e power)
393	{
394	  static const char *const names[] =
395	  {
396	    "light", "medium", "heavy"
397	  };
398	
399	  return power >= ROBOT_MOTION_PHASE_LIGHT &&
400	         power <= ROBOT_MOTION_PHASE_HEAVY ? names[power] : "unknown";
401	}
402	
403	static int robot_motion_phase_settle(int settle_ms,
404	                                     enum robot_motion_phase_power_e power)
405	{
406	  if (power == ROBOT_MOTION_PHASE_LIGHT)
407	    {
408	      settle_ms = settle_ms * 3 / 4;
409	      return settle_ms < 60 ? 60 : settle_ms;
410	    }
411	
412	  if (power == ROBOT_MOTION_PHASE_HEAVY)
413	    {
414	      settle_ms = settle_ms * 5 / 4;
415	      return settle_ms > 200 ? 200 : settle_ms;
416	    }
417	
418	  return settle_ms;
419	}
