421	static int robot_motion_execute_gait(
422	    const struct robot_motion_request_s *request)
423	{
424	  const struct robot_motion_gait_s *gait =
425	    robot_motion_gait(request->direction);
426	  struct robotctl_servo_ctx_s ctx;
427	  int interval_ms;
428	  int settle_ms;
429	  int ret;
430	  unsigned int cycle;
431	  unsigned int phase;
432	  unsigned int order;
433	  unsigned int active_servos;
434	  unsigned int heavy_phases = 0;
435	  enum robot_motion_phase_power_e power;
436	  int phase_settle_ms;
437	
438	  if (gait == NULL)
439	    {
440	      return -EINVAL;
441	    }
442	
443	  printf("[ROBOT-MOTION] backend init begin\n");
444	  ret = robotctl_servo_open(&ctx);
445	  printf("[ROBOT-MOTION] backend init done rc=%d\n", ret);
446	  if (ret < 0)
447	    {
448	      return ret;
449	    }
450	
451	  ctx.cancel_check = robot_motion_cancel_check;
452	  ctx.cancel_arg = NULL;
453	
454	  interval_ms = robot_motion_safe_interval(request->period_ms);
455	  settle_ms = robot_motion_safe_settle(request->period_ms);
456	  printf("[ROBOT-MOTION] power-aware profile requested=%u start=%d "
457	         "cruise=%d end=%d stagger=0 max_active=1 settle=%d\n",
458	         request->period_ms, interval_ms + interval_ms / 2, interval_ms,
459	         interval_ms + interval_ms / 4, settle_ms);
460	  printf("[ROBOT-MOTION] preparing request id=%lu home_required=yes\n",
461	         (unsigned long)request->request_id);
462	  ret = robot_motion_home_power_safe(&ctx, false);
463	  if (ret >= 0)
464	    {
465	      for (cycle = 0; cycle < request->steps && ret >= 0; cycle++)
466	        {
467	          for (phase = 0; phase < ROBOT_MOTION_PHASE_COUNT && ret >= 0;
468	               phase++)
469	            {
470	              if (robot_motion_cancel_check(NULL))
471	                {
472	                  ret = -ECANCELED;
473	                  break;
474	                }
475	
476	              power = robot_motion_phase_power(&ctx, &gait->phase[phase],
477	                                              &active_servos);
478	              phase_settle_ms = robot_motion_phase_settle(settle_ms, power);
479	              if (power == ROBOT_MOTION_PHASE_HEAVY)
480	                {
481	                  heavy_phases++;
482	                }
483	              printf("[ROBOT-MOTION] phase=%u class=%s active_servos=%u "
484	                     "settle=%d\n", phase + 1,
485	                     robot_motion_phase_power_name(power), active_servos,
486	                     phase_settle_ms);
487	              printf("[ROBOT-MOTION] %s phase %u/%d id=%lu\n",
488	                     gait->name, phase + 1, ROBOT_MOTION_PHASE_COUNT,
489	                     (unsigned long)request->request_id);
490	              for (order = 0; order < 2; order++)
491	                {
492	                  enum robotctl_servo_e servo = gait->phase[phase].order[order];
493	
494	                  printf("[ROBOT-MOTION] servo %s current=%d target=%d "
495	                         "update=%s\n",
496	                         robotctl_servo_name(servo), ctx.angle[servo],
497	                         gait->phase[phase].target[servo],
498	                         ctx.angle[servo] == gait->phase[phase].target[servo] ?
499	                         "no" : "yes");
500	                  if (ctx.angle[servo] == gait->phase[phase].target[servo])
501	                    {
502	                      continue;
503	                    }
504	
505	                  ret = robotctl_servo_move_one(
506	                    &ctx, servo, gait->phase[phase].target[servo],
507	                    interval_ms, phase_settle_ms);
508	                  if (ret < 0)
509	                    {
510	                      break;
511	                    }
512	                }
513	            }
514	        }
515	    }
516	
517	  if (ret >= 0)
518	    {
519	      ret = robot_motion_cancel_check(NULL) ? -ECANCELED :
520	            robot_motion_home_power_safe(&ctx, false);
521	    }
522	
523	  printf("[ROBOT-MOTION] summary writes=%u skipped=%u total_angle_delta=%u "
524	         "heavy_phases=%u\n", ctx.command_count, ctx.skipped_count,
525	         ctx.total_angle_delta, heavy_phases);
526	  robotctl_servo_close(&ctx);
527	  return ret;
528	}
