530	static int robot_motion_execute_tail_wag(
531	    const struct robot_motion_request_s *request)
532	{
533	  struct robotctl_servo_ctx_s ctx;
534	  const int center = g_robotctl_home[ROBOTCTL_TAIL];
535	  const int right = center + (int)request->amplitude_deg;
536	  const int left = center - (int)request->amplitude_deg;
537	  int interval_ms = robot_motion_tail_interval(request->period_ms);
538	  int cooldown_ms = robot_motion_tail_cooldown_ms(request->period_ms, request->amplitude_deg);
539	  int ret;
540	  unsigned int cycle;
541	
542	  printf("[ROBOT-MOTION] tail wag begin cycles=%u requested_amplitude=%u "
543	         "right_offset=%d left_offset=%d period_ms=%u interval_ms=%d "
544	         "cooldown_ms=%d segment_deg=%d profile=music_micro_wag\n",
545	         request->steps, request->amplitude_deg,
546	         (int)request->amplitude_deg, (int)request->amplitude_deg,
547	         request->period_ms, interval_ms, cooldown_ms,
548	         ROBOT_MOTION_TAIL_SEGMENT_DEG);
549	
550	  ret = robotctl_servo_open(&ctx);
551	  if (ret < 0)
552	    {
553	      return ret;
554	    }
555	
556	  ctx.cancel_check = robot_motion_cancel_check;
557	  ctx.cancel_arg = NULL;
558	  if (abs(ctx.angle[ROBOTCTL_TAIL] - center) > ROBOT_MOTION_TAIL_MAX_AMPLITUDE)
559	    {
560	      robotctl_servo_close(&ctx);
561	      return -ERANGE; /* Do not make a large centering move during music. */
562	    }
563	
564	  /*
565	   * Give the supply rail time to settle after opening the PWM backend.  This
566	   * is especially useful when music/TTS/audio amplification is already active.
567	   */
568	  ret = robot_motion_tail_cooldown(ROBOT_MOTION_TAIL_OPEN_RECOVERY_MS);
569	
570	  /* Return through center using only bounded one-degree tail pulses. */
571	  if (ret >= 0)
572	    {
573	      ret = robot_motion_tail_ramp_to(&ctx, center, interval_ms, cooldown_ms);
574	    }
575	
576	  for (cycle = 0; ret >= 0 && cycle < request->steps; cycle++)
577	    {
578	      if (robot_motion_cancel_check(NULL))
579	        {
580	          ret = -ECANCELED;
581	          break;
582	        }
583	
584	      printf("[ROBOT-MOTION] tail wag cycle=%u/%u sweep=center->right\n",
585	             cycle + 1, request->steps);
586	      ret = robot_motion_tail_ramp_to(&ctx, right, interval_ms, cooldown_ms);
587	
588	      if (ret >= 0)
589	        {
590	          printf("[ROBOT-MOTION] tail wag cycle=%u/%u sweep=right->left\n",
591	                 cycle + 1, request->steps);
592	          ret = robot_motion_tail_ramp_to(&ctx, left, interval_ms, cooldown_ms);
593	        }
594	
595	      if (ret >= 0)
596	        {
597	          printf("[ROBOT-MOTION] tail wag cycle=%u/%u sweep=left->center\n",
598	                 cycle + 1, request->steps);
599	          ret = robot_motion_tail_ramp_to(&ctx, center,
600	                                          interval_ms, cooldown_ms);
601	        }
602	    }
603	
604	  if (ret >= 0 && ctx.angle[ROBOTCTL_TAIL] != center)
605	    {
606	      ret = robot_motion_tail_ramp_to(&ctx, center,
607	                                      interval_ms, cooldown_ms);
608	    }
609	
610	  if (ret >= 0) ret = robot_motion_tail_cooldown(ROBOT_MOTION_TAIL_OPEN_RECOVERY_MS);
611	  robotctl_servo_close(&ctx);
612	  printf("[ROBOT-MOTION] tail wag done rc=%d\n", ret);
613	  return ret;
614	}
