/* Contest-local adapter for the Agent music API.
 *
 * The Agent still calls the robot_legacy_media_* ABI through the contest redirect,
 * but the implementation below is the local HTTP/Helix backend.  It does not
 * start mediad and does not depend on the OpenVela Media graph.
 */
#include <nuttx/config.h>

#include "robot_media_player.h"
#include "robot_music_media.h"

#include <errno.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <syslog.h>

#ifndef MEDIA_EVENT_STOPPED
#  define MEDIA_EVENT_STOPPED 4
#endif
#ifndef MEDIA_EVENT_COMPLETED
#  define MEDIA_EVENT_COMPLETED 6
#endif

struct rv_music_handle
{
  void *player;
  bool started;
  bool closing;
  unsigned int users;
  unsigned long run;
  void *event_cookie;
  robot_music_event_cb event_cb;
};

static pthread_mutex_t g_music_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_music_changed = PTHREAD_COND_INITIALIZER;
static struct rv_music_handle *g_active_music;

extern unsigned long robot_voice_music_run_id(void) __attribute__((weak));

void robot_music_media_link_anchor(void)
{
}

static void robot_music_media_event_bridge(void *cookie, int event,
                                           int result, const char *extra)
{
  struct rv_music_handle *handle = cookie;
  robot_music_event_cb callback;
  void *callback_cookie;

  if (handle == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_music_lock);
  if (event == MEDIA_EVENT_COMPLETED || event == MEDIA_EVENT_STOPPED)
    {
      handle->started = false;
      if (g_active_music == handle)
        {
          g_active_music = NULL;
        }
    }

  callback = handle->closing ? NULL : handle->event_cb;
  callback_cookie = handle->event_cookie;
  if (callback != NULL)
    {
      handle->users++;
    }
  pthread_mutex_unlock(&g_music_lock);

  if (callback != NULL)
    {
      callback(callback_cookie, event, result, extra);
      pthread_mutex_lock(&g_music_lock);
      handle->users--;
      pthread_cond_broadcast(&g_music_changed);
      pthread_mutex_unlock(&g_music_lock);
    }
}

void *robot_music_media_open(const char *stream)
{
  struct rv_music_handle *handle;

  syslog(LOG_INFO, "[RV-MUSIC] backend=contest-legacy-http-helix\n");

  handle = calloc(1, sizeof(*handle));
  if (handle == NULL)
    {
      errno = ENOMEM;
      return NULL;
    }

  handle->player = robot_legacy_media_open(stream);
  if (handle->player == NULL)
    {
      int error = errno != 0 ? errno : EIO;
      free(handle);
      errno = error;
      return NULL;
    }

  return handle;
}

int robot_music_media_close(void *opaque, int pending_stop)
{
  struct rv_music_handle *handle = opaque;
  int ret;

  if (handle == NULL)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&g_music_lock);
  handle->closing = true;
  if (g_active_music == handle)
    {
      g_active_music = NULL;
    }
  while (handle->users != 0)
    {
      pthread_cond_wait(&g_music_changed, &g_music_lock);
    }
  pthread_mutex_unlock(&g_music_lock);

  ret = robot_legacy_media_close(handle->player, pending_stop);
  free(handle);
  return ret;
}

int robot_music_media_prepare(void *opaque, const char *url,
                              const char *options)
{
  struct rv_music_handle *handle = opaque;

  if (handle == NULL)
    {
      return -EINVAL;
    }

  return robot_legacy_media_prepare(handle->player, url, options);
}

int robot_music_media_set_event_callback(void *opaque, void *cookie,
                                         robot_music_event_cb callback)
{
  struct rv_music_handle *handle = opaque;
  int ret;

  if (handle == NULL)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&g_music_lock);
  if (handle->closing)
    {
      pthread_mutex_unlock(&g_music_lock);
      return -ECANCELED;
    }
  handle->event_cookie = cookie;
  handle->event_cb = callback;
  pthread_mutex_unlock(&g_music_lock);

  ret = robot_legacy_media_set_event_callback(handle->player, handle,
                                        robot_music_media_event_bridge);
  if (ret < 0)
    {
      pthread_mutex_lock(&g_music_lock);
      handle->event_cookie = NULL;
      handle->event_cb = NULL;
      pthread_mutex_unlock(&g_music_lock);
    }

