   308	int robot_oled_init(void)
   309	{
   310	  pthread_attr_t attr;
   311	  int ret;
   312	
   313	  pthread_mutex_lock(&g_oled_queue.lock);
   314	  if (g_oled_initialized)
   315	    {
   316	      ret = g_oled_failed ? -ENODEV : 0;
   317	      pthread_mutex_unlock(&g_oled_queue.lock);
   318	      return ret;
   319	    }
   320	
   321	  g_oled_initialized = true;
   322	  g_oled_stop = false;
   323	  g_oled_ready = false;
   324	  g_oled_failed = false;
   325	  g_oled_queue.head = 0;
   326	  g_oled_queue.tail = 0;
   327	  g_oled_queue.count = 0;
   328	  pthread_mutex_unlock(&g_oled_queue.lock);
   329	
   330	  ret = pthread_attr_init(&attr);
   331	  if (ret == 0)
   332	    {
   333	      ret = pthread_attr_setstacksize(&attr, ROBOT_OLED_STACK);
   334	      if (ret == 0)
   335	        {
   336	          ret = pthread_create(&g_oled_thread, &attr, robot_oled_worker,
   337	                               NULL);
   338	        }
   339	
   340	      pthread_attr_destroy(&attr);
   341	    }
   342	
   343	  if (ret != 0)
   344	    {
   345	      pthread_mutex_lock(&g_oled_queue.lock);
   346	      g_oled_failed = true;
   347	      g_oled_initialized = false;
   348	      pthread_mutex_unlock(&g_oled_queue.lock);
   349	      printf("[RV-OLED] worker create failed rc=%d\n", ret);
   350	      return -ret;
   351	    }
   352	
   353	  pthread_mutex_lock(&g_oled_queue.lock);
   354	  g_oled_thread_valid = true;
   355	  pthread_mutex_unlock(&g_oled_queue.lock);
   356	
   357	  printf("[RV-OLED] worker created\n");
   358	  return 0;
   359	}
