   361	int robot_oled_stop(void)
   362	{
   363	  bool join_needed;
   364	
   365	  pthread_mutex_lock(&g_oled_queue.lock);
   366	  join_needed = g_oled_thread_valid;
   367	  g_oled_stop = true;
   368	  pthread_cond_broadcast(&g_oled_queue.available);
   369	  pthread_mutex_unlock(&g_oled_queue.lock);
   370	
   371	  if (join_needed)
   372	    {
   373	      pthread_join(g_oled_thread, NULL);
   374	    }
   375	
   376	  pthread_mutex_lock(&g_oled_queue.lock);
   377	  g_oled_thread_valid = false;
   378	  g_oled_initialized = false;
   379	  g_oled_ready = false;
   380	  g_oled_failed = false;
   381	  g_oled_queue.head = 0;
   382	  g_oled_queue.tail = 0;
   383	  g_oled_queue.count = 0;
   384	  pthread_mutex_unlock(&g_oled_queue.lock);
   385	
   386	  g_oled_dev = NULL;
   387	  memset(&g_oled_plane, 0, sizeof(g_oled_plane));
   388	  return 0;
   389	}
