   391	int robot_oled_submit(enum robot_expression_e expression)
   392	{
   393	  if (expression < 0 || expression >= ROBOT_EXPRESSION_COUNT)
   394	    {
   395	      return -EINVAL;
   396	    }
   397	
   398	  pthread_mutex_lock(&g_oled_queue.lock);
   399	
   400	  if (!g_oled_initialized || g_oled_stop)
   401	    {
   402	      pthread_mutex_unlock(&g_oled_queue.lock);
   403	      return -EAGAIN;
   404	    }
   405	
   406	  if (g_oled_failed)
   407	    {
   408	      pthread_mutex_unlock(&g_oled_queue.lock);
   409	      return -ENODEV;
   410	    }
   411	
   412	  /*
   413	   * Avoid piling up identical frames.  This also reduces I2C traffic when a
   414	   * caller repeats the same state while the worker is still busy.
   415	   */
   416	
   417	  if (g_oled_queue.count > 0)
   418	    {
   419	      unsigned int last =
   420	          (g_oled_queue.tail + ROBOT_OLED_QUEUE_DEPTH - 1) %
   421	          ROBOT_OLED_QUEUE_DEPTH;
   422	
   423	      if (g_oled_queue.slots[last] == expression)
   424	        {
   425	          pthread_mutex_unlock(&g_oled_queue.lock);
   426	          return 0;
   427	        }
   428	    }
   429	
   430	  if (g_oled_queue.count == ROBOT_OLED_QUEUE_DEPTH)
   431	    {
   432	      printf("[RV-OLED] queue full: dropping oldest expression=%d\n",
   433	             g_oled_queue.slots[g_oled_queue.head]);
   434	      g_oled_queue.head =
   435	          (g_oled_queue.head + 1) % ROBOT_OLED_QUEUE_DEPTH;
   436	      g_oled_queue.count--;
   437	    }
   438	
   439	  g_oled_queue.slots[g_oled_queue.tail] = expression;
   440	  g_oled_queue.tail =
   441	      (g_oled_queue.tail + 1) % ROBOT_OLED_QUEUE_DEPTH;
   442	  g_oled_queue.count++;
   443	
   444	  printf("[RV-OLED] enqueue expression=%d pending=%u ready=%d\n",
   445	         expression, g_oled_queue.count, g_oled_ready ? 1 : 0);
   446	
   447	  pthread_cond_signal(&g_oled_queue.available);
   448	  pthread_mutex_unlock(&g_oled_queue.lock);
   449	  return 0;
   450	}
