        for (struct ifaddrs *ifa = list; ifa; ifa = ifa->ifa_next) {
            if (!ifa->ifa_addr || ifa->ifa_addr->sa_family != AF_INET ||
                !ifa->ifa_name || (ifa->ifa_flags & IFF_LOOPBACK) ||
                !(ifa->ifa_flags & IFF_UP)) continue;
