static spinlock_t g_lock;

/* Wi-Fi allocation / TX memory diagnostics.
 *
 * Keep allocator-side diagnostics allocation-free: allocation wrappers only
 * increment counters.  Detailed heap state is printed from the TX call site
 * when the vendor driver reports ESP_ERR_NO_MEM.
 */

static volatile uint32_t g_wifi_alloc_fail_general;
static volatile uint32_t g_wifi_alloc_fail_internal;
static volatile uint32_t g_wifi_alloc_fail_wifi;
static uint32_t g_wifi_tx_nomem_count;


/* Reserve Wi-Fi TX buffers from internal/DMA-capable RAM at Wi-Fi init time.
 *
 * This board uses SPIRAM as part of the common heap.  Dynamic Wi-Fi TX
 * allocation can therefore receive an external-RAM block from kmm_malloc(),
 * which esp_malloc_internal() must reject.  Reserving a small static pool
 * before TLS/ASR allocations prevents that runtime failure.
 *
 * Keep this >= the WLAN upper-half TX in-flight limit (currently 4).
 */
#define CONTEST_WIFI_STATIC_TXBUF_NUM 8


static void esp_wifi_mem_diag(const char *site, size_t req, int raw_ret)
{
  struct mallinfo info = kmm_mallinfo();

  syslog(LOG_ERR,
         "[WIFI-MEM] site=%s raw_ret=%d req=%zu "
         "arena=%d used=%d free=%d largest=%d "
         "fail_general=%" PRIu32 " fail_internal=%" PRIu32
         " fail_wifi=%" PRIu32 "\n",
         site ? site : "?", raw_ret, req,
         info.arena, info.uordblks, info.fordblks, info.mxordblk,
         (uint32_t)g_wifi_alloc_fail_general,
         (uint32_t)g_wifi_alloc_fail_internal,
         (uint32_t)g_wifi_alloc_fail_wifi);
}

/****************************************************************************
 * Public Data

#ifdef CONFIG_ESP32S3_WIFI_RX_AMPDU
  wifi_cfg.ampdu_rx_enable = 1;
#else
  wifi_cfg.ampdu_rx_enable = 0;
#endif

#ifdef CONFIG_ESP32S3_WIFI_STA_DISCONNECT_PM
  wifi_cfg.sta_disconnected_pm = true;
#else
  wifi_cfg.sta_disconnected_pm = false;
#endif

  wifi_cfg.rx_ba_win          = CONFIG_ESP32S3_WIFI_RXBA_AMPDU_WZ;
  wifi_cfg.static_rx_buf_num  = CONFIG_ESP32S3_WIFI_STATIC_RXBUF_NUM;
  wifi_cfg.dynamic_rx_buf_num = CONFIG_ESP32S3_WIFI_DYNAMIC_RXBUF_NUM;

  /*
   * Force static Wi-Fi TX buffers for this PSRAM/common-heap target.
   *
   * esp_wifi.h defines tx_buf_type 0 as static and 1 as dynamic.  The
   * third-party sdkconfig defaults this target to dynamic TX, but dynamic TX
   * allocation is exactly what fails once TLS/ASR consumes the remaining
   * internal-capable heap.  Static buffers are allocated during esp_wifi_init
   * while internal RAM is still available and then reused for every send.
   */

  wifi_cfg.tx_buf_type        = 0; /* static TX buffer */
  wifi_cfg.static_tx_buf_num = CONTEST_WIFI_STATIC_TXBUF_NUM;
  wifi_cfg.dynamic_tx_buf_num = 0;

  syslog(LOG_INFO,
         "[WIFI-TXCFG] type=static(%d) static=%d dynamic=%d "
         "psram_common_heap=1\n",
         wifi_cfg.tx_buf_type,
         wifi_cfg.static_tx_buf_num,
         wifi_cfg.dynamic_tx_buf_num);

  ret = esp_wifi_init(&wifi_cfg);
  if (ret)
    {
      syslog(LOG_ERR,
             "[WIFI-TXCFG] esp_wifi_init failed raw_ret=%d mapped=%d\n",
             ret, wifi_errno_trans(ret));
      esp_wifi_mem_diag("wifi_init_static_tx", 0, ret);
      ret = wifi_errno_trans(ret);
      goto errout_init_wifi;
    }

  ret = esp_wifi_set_tx_done_cb(esp_wifi_tx_done_cb);
  if (ret)
    {
      wlerr("Failed to register TX done callback ret=%d\n", ret);
      ret = wifi_errno_trans(ret);
      goto errout_init_txdone;
    }

